// Generated by tooling/unicode-cases/normalization.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [802888133, 2831636933, 3718468037, 1959512517, 2528162245, 737823173, 2492105157, 2860933573, 2295030213, 2903960005, 2678108613, 2050941381, 103469509, 1422250437, 2912862661, 3189254597];
const blocks = ["NFC U+080000-U+080FFF", "NFC U+081000-U+081FFF", "NFC U+082000-U+082FFF", "NFC U+083000-U+083FFF", "NFC U+084000-U+084FFF", "NFC U+085000-U+085FFF", "NFC U+086000-U+086FFF", "NFC U+087000-U+087FFF", "NFC U+088000-U+088FFF", "NFC U+089000-U+089FFF", "NFC U+08A000-U+08AFFF", "NFC U+08B000-U+08BFFF", "NFC U+08C000-U+08CFFF", "NFC U+08D000-U+08DFFF", "NFC U+08E000-U+08EFFF", "NFC U+08F000-U+08FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 524288 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
